import {parseCoordinates,parseCoordinateLine,parseBearings,metrics,kml} from './geo.js';
const $=id=>document.getElementById(id);
const sample='14.112480, 120.954680\n14.112580, 120.955120\n14.112130, 120.955390\n14.111900, 120.955010\n14.112090, 120.954630';
let points=parseCoordinates(sample),mode='gps',map,markers=[],ready=false,isSample=true,closure=null,currentImageURL,worker,ocrBusy=false;
const empty={type:'FeatureCollection',features:[]};
const style={version:8,sources:{satellite:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,maxzoom:19,attribution:'Imagery © Esri, Maxar, Earthstar Geographics and the GIS User Community'},streets:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,maxzoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'},lot:{type:'geojson',data:empty}},layers:[{id:'satellite',type:'raster',source:'satellite'},{id:'streets',type:'raster',source:'streets',layout:{visibility:'none'}},{id:'lot-fill',type:'fill',source:'lot',paint:{'fill-color':'#d5ee93','fill-opacity':.20}},{id:'lot-outline-shadow',type:'line',source:'lot',paint:{'line-color':'#314b32','line-width':5,'line-opacity':.55}},{id:'lot-outline',type:'line',source:'lot',paint:{'line-color':'#deef9e','line-width':2.5}}]};
function feature(){return {type:'Feature',properties:{approximate:true},geometry:{type:'Polygon',coordinates:[[...points,points[0]]]}};}
function fit(){if(!ready)return;const b=new maplibregl.LngLatBounds();points.forEach(p=>b.extend(p));map.fitBounds(b,{padding:{top:130,bottom:300,left:85,right:85},maxZoom:19,duration:900});}
function update(){const {area,perimeter}=metrics(points);$('area').innerHTML=`${area.toLocaleString(undefined,{maximumFractionDigits:0})}<small>m²</small>`;$('perimeter').innerHTML=`${perimeter.toFixed(1)}<small>m</small>`;$('point-count').textContent=points.length.toString().padStart(2,'0');$('card-title').innerHTML=isSample?'Sample lot <span class="small-badge">Demo</span>':'Your lot <span class="small-badge">Review required</span>';$('lot-name').textContent=isSample?'Sample lot':'Your lot';$('lot-location').textContent=isSample?'Tagaytay, Philippines':'WGS 84 coordinates';$('sample-note').hidden=!isSample;$('boundary-status').textContent=closure===null?'● Closed boundary':`● Closure gap: ${closure.toFixed(2)} m`;$('points-list').replaceChildren(...points.map((p,i)=>{const row=document.createElement('div');row.className='point-row';for(const v of [String(i+1).padStart(2,'0'),p[1].toFixed(7),p[0].toFixed(7)]){const s=document.createElement('span');s.textContent=v;row.append(s);}return row;}));const centre=points.reduce((a,p)=>[a[0]+p[0]/points.length,a[1]+p[1]/points.length],[0,0]);$('google').href=`https://www.google.com/maps/search/?api=1&query=${centre[1]},${centre[0]}`;if(!ready)return;map.getSource('lot').setData(feature());markers.forEach(m=>m.remove());markers=points.map((p,i)=>{const el=document.createElement('div');el.className='corner';el.textContent=i+1;el.setAttribute('aria-label',`Corner ${i+1}`);return new maplibregl.Marker({element:el}).setLngLat(p).addTo(map);});}
try{if(!window.maplibregl)throw Error('The map library could not load. Check your connection and reload.');map=new maplibregl.Map({container:'map',style,center:[120.955,14.1122],zoom:17,attributionControl:true});map.addControl(new maplibregl.ScaleControl({maxWidth:90,unit:'metric'}),'bottom-left');map.on('load',()=>{ready=true;update();fit();});map.on('error',()=>{$('map-error').hidden=false;$('map-error').textContent='Some map tiles could not load. Check your connection or switch to Streets. Your boundary and export remain available.';});map.on('idle',()=>{if(map.areTilesLoaded())$('map-error').hidden=true;});}catch(e){$('map-error').hidden=false;$('map-error').textContent=e.message;}update();
function setMode(next){mode=next;$('gps-input').hidden=mode!=='gps';$('bearing-input').hidden=mode!=='bearing';$('gps-tab').classList.toggle('active',mode==='gps');$('bearing-tab').classList.toggle('active',mode==='bearing');$('input-error').textContent='';}
$('gps-tab').onclick=()=>setMode('gps');$('bearing-tab').onclick=()=>setMode('bearing');
function plot(){try{let result;if(mode==='gps'){result={points:parseCoordinates($('raw').value),closure:null};}else{result=parseBearings($('bearings').value,$('anchor-lat').value,$('anchor-lng').value);if(result.closure>Math.max(.5,metrics(result.points).perimeter*.001))throw Error(`The survey does not close: ${result.closure.toFixed(2)} m gap. Check each course, distance, and the final return line.`);}points=result.points;closure=result.closure;isSample=false;update();fit();$('input-error').textContent='';return {points:points.length,...metrics(points)};}catch(e){$('input-error').textContent=e.message;throw e;}}
$('plot').onclick=()=>{try{plot();}catch{}};
$('demo').onclick=()=>{if(ocrBusy)return;setMode('gps');$('raw').value=sample;points=parseCoordinates(sample);isSample=true;closure=null;update();fit();$('input-error').textContent='';};
$('fit').onclick=fit;$('zoom-in').onclick=()=>map?.zoomIn();$('zoom-out').onclick=()=>map?.zoomOut();$('north').onclick=()=>map?.easeTo({bearing:0,pitch:0});
function projection(globe){if(!ready)return;map.setProjection({type:globe?'globe':'mercator'});$('globe-view').classList.toggle('active',globe);$('map-view').classList.toggle('active',!globe);if(globe)map.flyTo({center:points[0],zoom:2,pitch:0,duration:1500});else fit();}
$('map-view').onclick=()=>projection(false);$('globe-view').onclick=()=>projection(true);
function layer(name){if(!ready)return;for(const id of ['satellite','streets']){map.setLayoutProperty(id,'visibility',id===name?'visible':'none');$(id).classList.toggle('active',id===name);}$('map-error').hidden=true;}
$('satellite').onclick=()=>layer('satellite');$('streets').onclick=()=>layer('streets');
$('export').onclick=()=>{const blob=new Blob([kml(points)],{type:'application/vnd.google-earth.kml+xml'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=isSample?'sample-lot.kml':'lot-boundary.kml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('points-toggle').onclick=()=>{$('points-panel').hidden=!$('points-panel').hidden;$('points-toggle').textContent=$('points-panel').hidden?'View points ↗':'Hide points ↙';};
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();
async function recognize(file){if(!file||ocrBusy)return;if(!['image/jpeg','image/png','image/webp','image/bmp'].includes(file.type)){$('ocr-status').textContent='Choose a JPG, PNG, WEBP, or BMP image. For a PDF, export the coordinate page as an image.';return;}if(file.size>20*1024*1024){$('ocr-status').textContent='This image is too large. Use a photo under 20 MB.';return;}ocrBusy=true;['file','demo','plot','gps-tab','bearing-tab'].forEach(id=>$(id).disabled=true);$('ocr-status').textContent='Preparing image…';$('filename').textContent=file.name;$('input-error').textContent='';if(currentImageURL)URL.revokeObjectURL(currentImageURL);currentImageURL=URL.createObjectURL(file);$('document-preview').src=currentImageURL;$('document-preview').hidden=false;$('raw').value='';$('bearings').value='';$('ocr-details').hidden=true;try{if(!window.Tesseract)throw Error('Text recognition could not load. Check your connection and try again.');worker=await Tesseract.createWorker('eng',1,{logger:m=>{if(m.status==='recognizing text')$('ocr-status').textContent=`Reading document… ${Math.round(m.progress*100)}%`;else $('ocr-status').textContent='Loading text recognition…';}});const {data}=await worker.recognize(file);$('ocr-text').textContent=data.text;$('ocr-details').hidden=false;const gps=[],courses=[];for(let line of data.text.split('\n')){line=line.trim();const decimal=line.match(/([-+]?\d{1,2}\.\d{4,})\s*[,;\s]\s*([-+]?\d{1,3}\.\d{4,})/);try{const p=parseCoordinateLine(decimal?`${decimal[1]}, ${decimal[2]}`:line);if(Math.abs(p[1])<=85&&Math.abs(p[0])<=180)gps.push(`${p[1].toFixed(7)}, ${p[0].toFixed(7)}`);}catch{}const course=line.match(/[NS]\s*\d[^NS\n]*?[EW]\s*[,;:]?\s*\d+(?:\.\d+)?\s*(?:m|meters|metres)?/i);if(course)courses.push(course[0]);}if(gps.length>=3){setMode('gps');$('raw').value=gps.join('\n');$('ocr-status').textContent=`Found ${gps.length} coordinate rows. Review them, then outline your lot.`;}else if(courses.length>=3){setMode('bearing');$('bearings').value=courses.join('\n');$('ocr-status').textContent=`Found ${courses.length} possible courses. Check them and enter a known first corner.`;}else{$('raw').value=gps.join('\n');$('ocr-status').textContent='No complete boundary found. Review the recognized text below and enter or correct the coordinates. Local grid coordinates need conversion first.';}}catch(e){$('ocr-status').textContent=`Could not read this image. ${e.message}`;}finally{if(worker){await worker.terminate().catch(()=>{});worker=null;}ocrBusy=false;['file','demo','plot','gps-tab','bearing-tab'].forEach(id=>$(id).disabled=false);$('file').value='';}}
$('file').onchange=e=>recognize(e.target.files[0]);$('dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click();}};for(const ev of ['dragenter','dragover'])$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.add('drag');});for(const ev of ['dragleave','drop'])$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.remove('drag');});$('dropzone').addEventListener('drop',e=>recognize(e.dataTransfer.files[0]));
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_lot_boundary',title:'Read lot boundary',description:'Read the currently displayed approximate WGS 84 boundary and measurements.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({sample:isSample,coordinates:points,closureGapMetres:closure,...metrics(points)})});}catch{}}
